from __future__ import annotations
import json
from typing import get_type_hints

import pytest
from _pytest.mark.structures import ParameterSet as Implementation

def helper() -> pytest.ParameterSet:
    return pytest.param(1)

def resolve(target):
    try:
        hints = get_type_hints(target)
    except (AttributeError, NameError, TypeError) as error:
        return {"error": type(error).__name__, "message": str(error)}
    if target is helper:
        return {"return_is_factory_type": hints.get("return") is type(helper())}
    return {"field_names": sorted(hints)}

print(json.dumps({"public_identity": getattr(pytest, "ParameterSet", None) is Implementation,
                  "helper": resolve(helper), "implementation_fields": resolve(Implementation)}, sort_keys=True))
